window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-33201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλίσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2883 na letra π · nº geral 33201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª pl. impf. ép. πλίσσοντο) (mula) ter uma boa andadura; galopar.</p></section></article>\n<article id=\"entry-dgp-33202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοιάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2884 na letra π · nº geral 33202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barquinho; bote. 〈πλοῖον〉</p></section></article>\n<article id=\"entry-dgp-33203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόϊμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2885 na letra π · nº geral 33203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πλώϊμος. 〈πλόος〉</p></section></article>\n<article id=\"entry-dgp-33204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2886 na letra π · nº geral 33204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 navio: πλ. ἀλιευτικόν xen. navio pesqueiro, πλοῖα ἱππαγωγά her. navios para o transporte de cavalos, πλοῖα μακρά her. navios longos ou navios de guerra, πλοῖα στρογγύλα ou φορτηγικά xen. navios de transporte 2 navio mercante, de transporte 3 trirreme. 〈πλόος 〉</p></section></article>\n<article id=\"entry-dgp-33205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόκαμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2887 na letra π · nº geral 33205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cacho de cabelo 2 pl. cabeleira cacheada 3 Cabeleira de Berenice, constelação 4 tentáculo (de polvo). 〈πλέκω〉</p></section></article>\n<article id=\"entry-dgp-33206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόκανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2888 na letra π · nº geral 33206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalho trançado em junco ou em vime 2 peneira 3 corda trançada. 〈πλέκω〉</p></section></article>\n<article id=\"entry-dgp-33207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοκή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2889 na letra π · nº geral 33207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de trançar 2 tecido 3 trama; entrelaçamento 4 combinação 5 intriga em um drama 6 complexidade (do discurso) 7 cilada. 〈πλέκω〉</p></section></article>\n<article id=\"entry-dgp-33208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2890 na letra π · nº geral 33208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">um tipo de colar ou de corrente. 〈πλόκος〉</p></section></article>\n<article id=\"entry-dgp-33209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2891 na letra π · nº geral 33209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 punhado ou cacho de cabelos 2 coroa trançada 3 corda de arco trançada. 〈πλέκω〉</p></section></article>\n<article id=\"entry-dgp-33210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 2892 na letra π · nº geral 33210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. πέλομαι.</p></section></article>\n<article id=\"entry-dgp-33211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόος-οῦς, όου-οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2893 na letra π · nº geral 33211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 navegação; travessia: prov. δεύ­τερος πλοῦς plat. segunda travessia, i.e., uma segunda tentativa após um fracasso 2 tempo ou vento favorável à navegação 3 trajeto por terra 4 o rastejar de serpente. 〈πλέω〉</p></section></article>\n<article id=\"entry-dgp-33212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2894 na letra π · nº geral 33212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esperar o momento favorável para embarcar. 〈πλοῦς, δοκέω〉</p></section></article>\n<article id=\"entry-dgp-33213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοθυγίεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2895 na letra π · nº geral 33213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o conjunto de riqueza e saúde. 〈πλοῦτος, ὑγίεια〉</p></section></article>\n<article id=\"entry-dgp-33214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 2896 na letra π · nº geral 33214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = πλόος.</p></section></article>\n<article id=\"entry-dgp-33215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουσιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2897 na letra π · nº geral 33215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de homem rico; suntuoso. 〈πλούσιος〉</p></section></article>\n<article id=\"entry-dgp-33216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλούσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2898 na letra π · nº geral 33216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 opulento; rico de algo, gen., dat. ou ἐν e dat. 2 copioso; abundante. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουσίως</h1><div class=\"entry-meta\"><span>DGP · ordem 2899 na letra π · nº geral 33217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ricamente; abundantemente.</p></section></article>\n<article id=\"entry-dgp-33218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλούταρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2900 na letra π · nº geral 33218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Plutarco, n. de h.</p></section></article>\n<article id=\"entry-dgp-33219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλουτεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2901 na letra π · nº geral 33219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pluteu, outro n. de Plutão.</p></section></article>\n<article id=\"entry-dgp-33220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2902 na letra π · nº geral 33220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser rico em algo, gen. ou dat.; de algo, gen. 2 tornar-se rico; enriquecer. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2903 na letra π · nº geral 33221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que proporciona riqueza. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 2904 na letra π · nº geral 33222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de πλουτέω.</p></section></article>\n<article id=\"entry-dgp-33223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2905 na letra π · nº geral 33223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enriquecer ♦ pas. 2 enriquecer-se; ser rico de algo, dat. ou ἀπό, ἐκ e gen. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτίνδην</h1><div class=\"entry-meta\"><span>DGP · ordem 2906 na letra π · nº geral 33224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. escolhendo entre os mais ricos; conforme a riqueza, a renda. 〈πλοῦτος, -ινδην〉</p></section></article>\n<article id=\"entry-dgp-33225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλουτίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2907 na letra π · nº geral 33225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Plutis, i.e. a Riqueza, os Ricos, partido político em Mileto, facção rica. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτογαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2908 na letra π · nº geral 33226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. abundante em riqueza; rico; opulento. 〈πλοῦτος, γηθέω〉</p></section></article>\n<article id=\"entry-dgp-33227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτοδότης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2909 na letra π · nº geral 33227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) doador de riquezas; que faz enriquecer. 〈πλοῦτος, δίδωμι〉</p></section></article>\n<article id=\"entry-dgp-33228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτοκρατία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2910 na letra π · nº geral 33228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">governo ou dominação exercida pelos ricos. 〈πλοῦτος, κράτος 〉</p></section></article>\n<article id=\"entry-dgp-33229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2911 na letra π · nº geral 33229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz ficar rico; que enriquece. 〈πλοῦτος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-33230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοῦτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2912 na letra π · nº geral 33230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 riqueza, gen.: πλ. χρυσοῦ, ἀργύρου her. fortuna em ouro, em prata 2 riqueza ou tesouro (do coração, da alma) ♦ Πλοῦτος 3 Pluto, deus da riqueza.</p></section></article>\n<article id=\"entry-dgp-33231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2913 na letra π · nº geral 33231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que proporciona riquezas. 〈πλοῦ­τος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-33232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλουτόχθων, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 2914 na letra π · nº geral 33232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) nascido de uma terra rica ou fecunda. 〈πλοῦτος, χθών〉</p></section></article>\n<article id=\"entry-dgp-33233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλούτων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2915 na letra π · nº geral 33233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Plutão, outro n. do deus Hades e n. de um rio fictício. 〈πλοῦτος〉</p></section></article>\n<article id=\"entry-dgp-33234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλουτώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2916 na letra π · nº geral 33234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gruta de Plutão, qualquer lugar envolvido por vapores nocivos que sugere a entrada do mundo dos mortos. 〈Πλούτων〉</p></section></article>\n<article id=\"entry-dgp-33235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλουτωνίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2917 na letra π · nº geral 33235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esposa de Plutão, i.e., Perséfone. 〈Πλούτων〉</p></section></article>\n<article id=\"entry-dgp-33236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοχμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2918 na letra π · nº geral 33236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cacho de cabelos 2 tentáculo de polvo. 〈πλέκω〉</p></section></article>\n<article id=\"entry-dgp-33237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλύνα</h1><div class=\"entry-meta\"><span>DGP · ordem 2919 na letra π · nº geral 33237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de πλύνω.</p></section></article>\n<article id=\"entry-dgp-33238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλύνεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 2920 na letra π · nº geral 33238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de πλύνω.</p></section></article>\n<article id=\"entry-dgp-33239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλυνέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2921 na letra π · nº geral 33239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ép. de πλύνω.</p></section></article>\n<article id=\"entry-dgp-33240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλυνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2922 na letra π · nº geral 33240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bacia ou tanque de lavar: πλύνον με ποιῶν ar. fazendo de mim uma bacia de lavar, i.e., enlameando-me ou crivando-me com injúrias ignóbeis. 〈πλύνω〉</p></section></article>\n<article id=\"entry-dgp-33241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πλυντήρια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 2923 na letra π · nº geral 33241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Plintérias, festa em Atenas no dia 25 do mês targelião, quando se lavavam os ornamentos da estátua da deusa Atena. 〈πλύνω〉</p></section></article>\n<article id=\"entry-dgp-33242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2924 na letra π · nº geral 33242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔπλυνον, fut. πλυνῶ, aor. ἔπλυνα, perf. desus.; pas. fut. πλυθήσομαι, aor. ἐπλύθην, perf. πέπλυσ­μαι) 1 lavar; limpar 2 remover lavando (mancha, sujeira) 3 gastar de tanto lavar 4 despejar uma enxurrada de admoestações ou críticas em alguém, ac.</p></section></article>\n<article id=\"entry-dgp-33243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλύσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2925 na letra π · nº geral 33243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lixívia; lavagem (de roupa suja). 〈πλύνω〉</p></section></article>\n<article id=\"entry-dgp-33244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλωάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2926 na letra π · nº geral 33244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que flutua (ave aquática, ilha). 〈πλώω〉</p></section></article>\n<article id=\"entry-dgp-33245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλωϊάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2927 na letra π · nº geral 33245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = πλωάς.</p></section></article>\n<article id=\"entry-dgp-33246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλώϊζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2928 na letra π · nº geral 33246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπλώιζον) navegar.</p></section></article>\n<article id=\"entry-dgp-33247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλώϊμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2929 na letra π · nº geral 33247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para a navegação: πλωίμων γενομένων tuc. ou ὄντων tuc. estando as circunstâncias favoráveis para a navegação 2 próprio para a construção de navios. 〈πλώω〉</p></section></article>\n<article id=\"entry-dgp-33248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλώσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2930 na letra π · nº geral 33248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πλώϊμος.</p></section></article>\n<article id=\"entry-dgp-33249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλωτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2931 na letra π · nº geral 33249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 homem do mar; navegador; remador 2 nadador. 〈πλώω〉</p></section></article>\n<article id=\"entry-dgp-33250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2932 na letra π · nº geral 33250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se dedica à navegação ♦ ὁ πλω­τικός 2 armador; proprietário de navio 2 pl. pessoas do mar. 〈πλώω〉</p></section></article>\n<article id=\"entry-dgp-33251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2933 na letra π · nº geral 33251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 navegável; acessível aos navios 2 que flutua; que bóia 3 que nada 4 que viaja pela água. 〈πλώω〉</p></section></article>\n<article id=\"entry-dgp-33252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλώω</h1><div class=\"entry-meta\"><span>DGP · ordem 2934 na letra π · nº geral 33252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = πλέω.</p></section></article>\n<article id=\"entry-dgp-33253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνείω</h1><div class=\"entry-meta\"><span>DGP · ordem 2935 na letra π · nº geral 33253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = πνέω.</p></section></article>\n<article id=\"entry-dgp-33254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνεῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2936 na letra π · nº geral 33254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sopro 2 sopro do vento; vento 3 vento da fortuna; sopro da prosperidade; o sopro favorável 4 respiração; sopro da vida 5 expiração do ar aspirado; hálito 6 exalação; odor 7 Medic. flato 8 sopro de entusiasmo, de ardor; suspiro, como sinal de força, de paixão 9 sopro divino; espírito divino 10 espírito 11 crist. Espírito Santo 12 bíbl. espírito maligno 13 ser espiritual ou imaterial 14 Gram. espírito rude ou doce, sinal de presença ou ausência de aspiração 15 Ret. sentença proferida de um só fôlego.</p></section></article>\n<article id=\"entry-dgp-33255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2937 na letra π · nº geral 33255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do sopro 2 da respiração 3 Ret. que permite retomar o fôlego; periódico; pausado 4 com sopro vital 5 espiritual; imaterial; incorpóreo 6 do ar; aéreo 7 que solta flatos 8 que exala odor 9 que produz ventos. 〈πνεῦμα〉</p></section></article>\n<article id=\"entry-dgp-33256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευμάτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2938 na letra π · nº geral 33256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sopro de vida; sopro 2 vida miserável. 〈πνεῦμα〉</p></section></article>\n<article id=\"entry-dgp-33257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2939 na letra π · nº geral 33257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transformar em vento ou vapor 2 encher de vento; inflar 3 Medic. causar flatulência 4 pas. evaporar 5 inflar-se 6 Medic. fermentar. 〈πνεῦμα〉</p></section></article>\n<article id=\"entry-dgp-33258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευματώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2940 na letra π · nº geral 33258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de fôlego curto; asmático 2 da natureza do vento ou do ar 3 exposto ao vento; sob o domínio do vento 4 Gram. pronunciado ou escrito com aspiração; aspirado 5 Medic. que sofre de flatulência 6 que produz ventos. 〈πνεῦμα, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-33259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευμάτωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2941 na letra π · nº geral 33259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 evaporação 2 inflação causada por ventos. 〈πνευματόω〉</p></section></article>\n<article id=\"entry-dgp-33260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευμονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2942 na letra π · nº geral 33260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pneumonia. 〈πνεῦμων〉</p></section></article>\n<article id=\"entry-dgp-33261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνεύμων, ονος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2943 na letra π · nº geral 33261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pulmão 2 sede de sentimentos 3 brânquia. 〈πλεύμων〉</p></section></article>\n<article id=\"entry-dgp-33262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνευστιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2944 na letra π · nº geral 33262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter fôlego curto; ser asmático. 〈πνέω〉</p></section></article>\n<article id=\"entry-dgp-33263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2945 na letra π · nº geral 33263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πνεύσω, át. πνευσοῦμαι, aor. ἔπνευσα, perf. πέπνευκα; pas. aor. ἐπνεύσθην, perf. πέπνυμαι) 1 intr. (vento) soprar: Ζεφύροιο λιγὺ πνείοντος ἀήτας hom. o sopro de Zéfiro que sopra sonoro, ὁ πνέων luc. o vento que sopra, ἡ πνέουσα n.t. a brisa que sopra 2 respirar; estar vivo: πάντων ὅσσα τε γαῖαν ἔπι πνείει τε καὶ ἕρπει hom. tudo quanto respira e caminha na terra, οἱ πνέοντες sóf. os vivos 3 respirar; exalar; deixar transparecer; manifestar; expressar, ac.: πν. μένεα hom. respirar coragem, πν. φόνον ésql. exalar assassínio, πν. ὠδῖνας eur. exalar, manifestar dor, πν. κότον ésql. respirar, exalar rancor 4 respirar; nutrir-se de; ser movido a, gen. ou dat.: πνέοντας δόρυ καὶ λόγχας ar. respirando espadas e lanças, πν. Ἄρεα ésql. respirar Ares, i.e., combates, πῦρ πνειόντων ἄστρων sóf. dos astros que respiram fogo, i.e., resplandecentes, θρασείᾳ πνέων καρδίᾳ pínd. exalando uma nobre audácia 5 dar-se ares; orgulhar-se, com predic.: πν. μέγας eur. dar-se grandes ares, orgulhar-se demais 6 bufar; exasperar-se; enfuriar-se: πν. μέγα eur. bufar forte, exasperar-se muito 7 soprar com força: πν. ὕπνῳ ésql. respirar ruidosamente durante o sono, roncar, πν. ὑπὲρ σακέων hes. roncar por cima dos escudos 8 exalar odor de, gen. ou dat.: πν. ἡδύ hom. exalar odor agradável ♦ pas. perf. πεπνῦσθαι 9 ser sensato: πεπνυμένος prudente, sensato, τὰ θεῖα πεπνυμένος plut. conhecedor das coisas divinas.</p></section></article>\n<article id=\"entry-dgp-33264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνιγηρός, ό, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2946 na letra π · nº geral 33264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sufocante; estreito; apertado (lugar). 〈πνίγω〉</p></section></article>\n<article id=\"entry-dgp-33265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνῖγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2947 na letra π · nº geral 33265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πνιγμός.</p></section></article>\n<article id=\"entry-dgp-33266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνιγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2948 na letra π · nº geral 33266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. sufocamento; asfixia 2 calor sufocante. 〈πνίγω〉</p></section></article>\n<article id=\"entry-dgp-33267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνῖγος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2949 na letra π · nº geral 33267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 calor sufocante; canícula 2 Dram. sufocação, versos da parábase da comédia antiga proferidos de um só fólego. 〈πνίγω〉</p></section></article>\n<article id=\"entry-dgp-33268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνίγω</h1><div class=\"entry-meta\"><span>DGP · ordem 2950 na letra π · nº geral 33268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πνίξω e πνίξομαι, aor. ἔπνιξα, perf. desus.; pas. fut.2 πνιγήσομαι, aor.2 ἐπνίγην, perf. πέπνιγμαι) 1 estrangular; sufocar 2 impes. sufocar de calor: πνίγει artt. faz calor sufocante 3 incomodar; atormentar 4 cozinhar em panela bem fechada; guisar.</p></section></article>\n<article id=\"entry-dgp-33269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνιγώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2951 na letra π · nº geral 33269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sufocante (calor) 2 Medic. que asfixia 3 sufocado. 〈πνῖγος, -ώδης〉</p></section></article>\n<article id=\"entry-dgp-33270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνικτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2952 na letra π · nº geral 33270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bíbl. estrangulado (animal) 2 cozido; guisado. 〈πνίγω〉</p></section></article>\n<article id=\"entry-dgp-33271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνοή,</h1><div class=\"entry-meta\"><span>DGP · ordem 2953 na letra π · nº geral 33271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ép. πνοιή, ῆς (ἡ) 1 sopro (do vento): πνοιαὶ ἀνέμων hom. sopros dos ventos 2 respiração; hálito: πνόας πνέω eur. eu respiro, πνοὴ Ἡφαίστοιο hom. sopro de Hefesto, i.e., sopro ardente do fogo, πν. Ἀφροδίτης eur. sopro de Afrodite, i.e., do amor, πν. Ἄρεος ésql. sopro de Ares, i.e., da guerra 3 som leve: πν. αὐλῶν pínd. sopro, som de flautas, πν. σύριγγος eur. murmúrio de caniços, de sírinx 4 exalação; odor. 〈πνέω〉</p></section></article>\n<article id=\"entry-dgp-33272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πνοιή</h1><div class=\"entry-meta\"><span>DGP · ordem 2954 na letra π · nº geral 33272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ép. = πνοή.</p></section></article>\n<article id=\"entry-dgp-33273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πνύξ,</h1><div class=\"entry-meta\"><span>DGP · ordem 2955 na letra π · nº geral 33273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. Πυκνός e Πνυκός (ἡ) Pnix, em Atenas, sede das assembléias do povo, a oeste da acrópole.</p></section></article>\n<article id=\"entry-dgp-33274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2956 na letra π · nº geral 33274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 erva 2 forragem 3 tapete de grama 4 verdura; folhagem 5 estação das verduras, i.e., verão.</p></section></article>\n<article id=\"entry-dgp-33275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαβρός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2957 na letra π · nº geral 33275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pés delicados. 〈ποῦς, ἁβρός〉</p></section></article>\n<article id=\"entry-dgp-33276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαγός</h1><div class=\"entry-meta\"><span>DGP · ordem 2958 na letra π · nº geral 33276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ποδηγός.</p></section></article>\n<article id=\"entry-dgp-33277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδάγρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2959 na letra π · nº geral 33277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 armadilha que prende o animal pelo pé 2 instrumento de tortura 3 Medic. gota nos pés; podagra. 〈ποῦς, ἀγρέω〉</p></section></article>\n<article id=\"entry-dgp-33278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαγράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2960 na letra π · nº geral 33278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter podagra; sofrer de gota nos pés. 〈πο­δάγρα〉</p></section></article>\n<article id=\"entry-dgp-33279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαγρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2961 na letra π · nº geral 33279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem podagra 2 de podagra ♦ τὰ ποδαγρικά 3 podagra. 〈ποδάγρα〉</p></section></article>\n<article id=\"entry-dgp-33280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαγρός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2962 na letra π · nº geral 33280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ποδαγρικός.</p></section></article>\n<article id=\"entry-dgp-33281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδανιπτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2963 na letra π · nº geral 33281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bacia para os pés. 〈ποῦς, νίπτω〉</p></section></article>\n<article id=\"entry-dgp-33282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδάνιπτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2964 na letra π · nº geral 33282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">água do banho dos pés; água para lavar os pés. 〈ποῦς, νίπτω〉</p></section></article>\n<article id=\"entry-dgp-33283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδαπός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2965 na letra π · nº geral 33283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de que país? 2 de que tipo? qual?</p></section></article>\n<article id=\"entry-dgp-33284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδένδυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2966 na letra π · nº geral 33284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">longo até os pés (mortalha). 〈ποῦς, ενδύω〉</p></section></article>\n<article id=\"entry-dgp-33285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόδεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 2967 na letra π · nº geral 33285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. ép. de πούς.</p></section></article>\n<article id=\"entry-dgp-33286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδεών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2968 na letra π · nº geral 33286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pata que faz parte da pele de animal escorchado: ἄκρων δέρμα λέοντος ἀφημμένον ἐκ ποδεώνων teócr. pele de leão presa pelas pontas da pata, i.e., pelas garras (nos ombros de Amico) 2 pele de carneiro 3 gargalo; bocal (de odre) 4 corda de vela (de navio) 5 estreito de terra; istmo. 〈ποῦς〉</p></section></article>\n<article id=\"entry-dgp-33287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδηγός,</h1><div class=\"entry-meta\"><span>DGP · ordem 2969 na letra π · nº geral 33287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. e át. ant. ποδαγός, ός, όν 1 que guia ♦ ὁ ποδαγός 2 guia; servo. 〈ποῦς, ἡγέομαι〉</p></section></article>\n<article id=\"entry-dgp-33288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδηνεκής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2970 na letra π · nº geral 33288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cai até os pés. 〈ποῦς, ἐνέγκειν〉</p></section></article>\n<article id=\"entry-dgp-33289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδήνεμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2971 na letra π · nº geral 33289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pés ágeis, rápidos como o vento. 〈ποῦς, ἄνεμος〉</p></section></article>\n<article id=\"entry-dgp-33290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2972 na letra π · nº geral 33290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que desce até os pés (veste, escudo) 2 que tem pés; ajustado com pés: στῦλος π. ésql. coluna que repousa no chão ♦ τὰ ποδήρη 3 pés. 〈ποῦς, ἄρω〉</p></section></article>\n<article id=\"entry-dgp-33291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδί</h1><div class=\"entry-meta\"><span>DGP · ordem 2973 na letra π · nº geral 33291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. sing. de πούς.</p></section></article>\n<article id=\"entry-dgp-33292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2974 na letra π · nº geral 33292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do comprimento ou largura ou altura de um pé 2 de bolinas: ποδιαῖον ποεῖσθαι artt. manobrar as velas com bolinas ♦ ἡ ποδιαία 3 lateral longa de um pé, usada como medida. 〈ποῦς〉</p></section></article>\n<article id=\"entry-dgp-33293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2975 na letra π · nº geral 33293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. aor. e perf. pas.) 1 fixar os pés (de animais) com peias 2 colocar pés; munir de pés.</p></section></article>\n<article id=\"entry-dgp-33294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδιστήρ, ῆρος</h1><div class=\"entry-meta\"><span>DGP · ordem 2976 na letra π · nº geral 33294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que cai até os pés 2 munido de pés. 〈ποδίζω〉</p></section></article>\n<article id=\"entry-dgp-33295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδῖιν</h1><div class=\"entry-meta\"><span>DGP · ordem 2977 na letra π · nº geral 33295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen.dat. dual homér. de πούς.</p></section></article>\n<article id=\"entry-dgp-33296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδοκάκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2978 na letra π · nº geral 33296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peias, travas de madeira. 〈πούς, κακός〉</p></section></article>\n<article id=\"entry-dgp-33297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδοκτύπη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2979 na letra π · nº geral 33297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dançarina. 〈πούς, κτυπέω〉</p></section></article>\n<article id=\"entry-dgp-33298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδονιπτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2980 na letra π · nº geral 33298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ποδανιπτήρ.</p></section></article>\n<article id=\"entry-dgp-33299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδοστράβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2981 na letra π · nº geral 33299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">instrumentο de cirurgia ou de tortura para contorcer os pés.</p></section></article>\n<article id=\"entry-dgp-33300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ποδόψηστρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2982 na letra π · nº geral 33300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tapete; capacho. 〈 πούς, φάω〉</p></section></article>\n";
